    const flowProjects = uipxResult.uipx.Projects.filter((project) => project.Type === "Flow");
    if (flowProjects.length === 0) {
      throw new Error(`No Flow project found in solution directory ${absolutePath}. Provide --path pointing to a Flow project directory.`);
    }
    const flowProjectPaths = flowProjects.map((project) => this.fs.path.join(absolutePath, this.fs.path.dirname(project.ProjectRelativePath)));
    if (flowProjects.length > 1) {
      throw new Error(`Multiple Flow projects found in solution directory ${absolutePath}. Provide --path pointing to one of: ${flowProjectPaths.join(", ")}`);
    }
